export type HsvaColor = {
  h: number
  s: number
  v: number
  a: number
}

export type ColorFormat =
  | "hex"
  | "hex8"
  | "rgb"
  | "rgba"
  | "hsl"
  | "hsla"

function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n))
}

function round(n: number, digits = 0) {
  const p = 10 ** digits
  return Math.round(n * p) / p
}

export function hsvaToRgba(hsva: HsvaColor): {
  r: number
  g: number
  b: number
  a: number
} {
  const h = ((hsva.h % 360) + 360) % 360
  const s = clamp(hsva.s, 0, 100) / 100
  const v = clamp(hsva.v, 0, 100) / 100
  const a = clamp(hsva.a, 0, 1)
  const c = v * s
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1))
  const m = v - c
  let rp = 0
  let gp = 0
  let bp = 0
  if (h < 60) [rp, gp, bp] = [c, x, 0]
  else if (h < 120) [rp, gp, bp] = [x, c, 0]
  else if (h < 180) [rp, gp, bp] = [0, c, x]
  else if (h < 240) [rp, gp, bp] = [0, x, c]
  else if (h < 300) [rp, gp, bp] = [x, 0, c]
  else [rp, gp, bp] = [c, 0, x]
  return {
    r: Math.round((rp + m) * 255),
    g: Math.round((gp + m) * 255),
    b: Math.round((bp + m) * 255),
    a,
  }
}

export function rgbaToHsva(
  r: number,
  g: number,
  b: number,
  a = 1
): HsvaColor {
  const rn = clamp(r, 0, 255) / 255
  const gn = clamp(g, 0, 255) / 255
  const bn = clamp(b, 0, 255) / 255
  const max = Math.max(rn, gn, bn)
  const min = Math.min(rn, gn, bn)
  const d = max - min
  let h = 0
  if (d !== 0) {
    if (max === rn) h = ((gn - bn) / d) % 6
    else if (max === gn) h = (bn - rn) / d + 2
    else h = (rn - gn) / d + 4
    h *= 60
    if (h < 0) h += 360
  }
  const s = max === 0 ? 0 : (d / max) * 100
  const v = max * 100
  return { h: round(h, 1), s: round(s, 1), v: round(v, 1), a: clamp(a, 0, 1) }
}

export function hsvaToHsla(hsva: HsvaColor): {
  h: number
  s: number
  l: number
  a: number
} {
  const s = clamp(hsva.s, 0, 100) / 100
  const v = clamp(hsva.v, 0, 100) / 100
  const l = v * (1 - s / 2)
  const sl = l === 0 || l === 1 ? 0 : (v - l) / Math.min(l, 1 - l)
  return {
    h: round(((hsva.h % 360) + 360) % 360, 1),
    s: round(sl * 100, 1),
    l: round(l * 100, 1),
    a: clamp(hsva.a, 0, 1),
  }
}

export function hslaToHsva(
  h: number,
  s: number,
  l: number,
  a = 1
): HsvaColor {
  const sn = clamp(s, 0, 100) / 100
  const ln = clamp(l, 0, 100) / 100
  const v = ln + sn * Math.min(ln, 1 - ln)
  const sv = v === 0 ? 0 : 2 * (1 - ln / v)
  return {
    h: ((h % 360) + 360) % 360,
    s: round(sv * 100, 1),
    v: round(v * 100, 1),
    a: clamp(a, 0, 1),
  }
}

function toHexByte(n: number) {
  return clamp(Math.round(n), 0, 255).toString(16).padStart(2, "0")
}

export function hsvaToHex(hsva: HsvaColor, withAlpha = false): string {
  const { r, g, b, a } = hsvaToRgba(hsva)
  const hex = `#${toHexByte(r)}${toHexByte(g)}${toHexByte(b)}`
  if (!withAlpha) return hex.toUpperCase()
  return `${hex}${toHexByte(Math.round(a * 255))}`.toUpperCase()
}

export function formatColor(hsva: HsvaColor, format: ColorFormat): string {
  const { r, g, b, a } = hsvaToRgba(hsva)
  const hsla = hsvaToHsla(hsva)
  switch (format) {
    case "hex":
      return hsvaToHex(hsva, false)
    case "hex8":
      return hsvaToHex(hsva, true)
    case "rgb":
      return `rgb(${r}, ${g}, ${b})`
    case "rgba":
      return `rgba(${r}, ${g}, ${b}, ${round(a, 3)})`
    case "hsl":
      return `hsl(${round(hsla.h, 1)} ${round(hsla.s, 1)}% ${round(hsla.l, 1)}%)`
    case "hsla":
      return `hsla(${round(hsla.h, 1)} ${round(hsla.s, 1)}% ${round(hsla.l, 1)}% / ${round(a, 3)})`
    default:
      return hsvaToHex(hsva, false)
  }
}

function parseHex(raw: string): HsvaColor | null {
  const hex = raw.replace(/^#/, "").trim()
  if (!/^[0-9a-fA-F]{3}$|^[0-9a-fA-F]{4}$|^[0-9a-fA-F]{6}$|^[0-9a-fA-F]{8}$/.test(hex)) {
    return null
  }
  let r = 0
  let g = 0
  let b = 0
  let a = 1
  if (hex.length === 3 || hex.length === 4) {
    r = parseInt(hex[0] + hex[0], 16)
    g = parseInt(hex[1] + hex[1], 16)
    b = parseInt(hex[2] + hex[2], 16)
    if (hex.length === 4) a = parseInt(hex[3] + hex[3], 16) / 255
  } else {
    r = parseInt(hex.slice(0, 2), 16)
    g = parseInt(hex.slice(2, 4), 16)
    b = parseInt(hex.slice(4, 6), 16)
    if (hex.length === 8) a = parseInt(hex.slice(6, 8), 16) / 255
  }
  return rgbaToHsva(r, g, b, a)
}

export function parseColor(input: string): HsvaColor | null {
  const value = input.trim()
  if (!value) return null

  if (value.startsWith("#") || /^[0-9a-fA-F]{3,8}$/.test(value)) {
    return parseHex(value.startsWith("#") ? value : `#${value}`)
  }

  const rgbMatch = value.match(
    /^rgba?\(\s*([\d.]+)\s*,?\s*([\d.]+)\s*,?\s*([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/i
  )
  if (rgbMatch) {
    const aRaw = rgbMatch[4]
    const a =
      aRaw == null
        ? 1
        : aRaw.endsWith("%")
          ? parseFloat(aRaw) / 100
          : parseFloat(aRaw)
    return rgbaToHsva(
      parseFloat(rgbMatch[1]),
      parseFloat(rgbMatch[2]),
      parseFloat(rgbMatch[3]),
      Number.isFinite(a) ? a : 1
    )
  }

  const hslMatch = value.match(
    /^hsla?\(\s*([\d.]+)\s*,?\s*([\d.]+)%\s*,?\s*([\d.]+)%(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/i
  )
  if (hslMatch) {
    const aRaw = hslMatch[4]
    const a =
      aRaw == null
        ? 1
        : aRaw.endsWith("%")
          ? parseFloat(aRaw) / 100
          : parseFloat(aRaw)
    return hslaToHsva(
      parseFloat(hslMatch[1]),
      parseFloat(hslMatch[2]),
      parseFloat(hslMatch[3]),
      Number.isFinite(a) ? a : 1
    )
  }

  return null
}

export function normalizeColorString(
  input: string,
  format: ColorFormat = "hex"
): string | null {
  const hsva = parseColor(input)
  if (!hsva) return null
  return formatColor(hsva, format)
}

export function colorsEqual(a: string, b: string): boolean {
  const ca = parseColor(a)
  const cb = parseColor(b)
  if (!ca || !cb) return a.trim().toLowerCase() === b.trim().toLowerCase()
  return (
    Math.abs(ca.h - cb.h) < 0.5 &&
    Math.abs(ca.s - cb.s) < 0.5 &&
    Math.abs(ca.v - cb.v) < 0.5 &&
    Math.abs(ca.a - cb.a) < 0.01
  )
}

export const DEFAULT_SWATCHES = [
  "#EF4444",
  "#F97316",
  "#EAB308",
  "#22C55E",
  "#14B8A6",
  "#3B82F6",
  "#8B5CF6",
  "#EC4899",
  "#64748B",
  "#0F172A",
  "#FFFFFF",
  "#000000",
]

"use client"

import * as React from "react"
import { CheckIcon, CopyIcon, PipetteIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { Slider } from "@/components/ui/slider"
import { cn } from "@/lib/utils"

import {
  type ColorFormat,
  type HsvaColor,
  DEFAULT_SWATCHES,
  colorsEqual,
  formatColor,
  hsvaToHex,
  hsvaToRgba,
  parseColor,
} from "./color-utils"

export type ColorPickerProps = {
  value?: string
  defaultValue?: string
  onValueChange?: (
    value: string,
    meta: { hsva: HsvaColor; format: ColorFormat }
  ) => void
  format?: ColorFormat
  defaultFormat?: ColorFormat
  onFormatChange?: (format: ColorFormat) => void
  swatches?: string[]
  swatchColumns?: number
  disabledSwatches?: string[]
  recentColors?: string[]
  defaultRecentColors?: string[]
  onRecentColorsChange?: (colors: string[]) => void
  showOpacity?: boolean
  showEyeDropper?: boolean
  showCopy?: boolean
  showFormatSelect?: boolean
  showSwatches?: boolean
  showRecent?: boolean
  disabled?: boolean
  readOnly?: boolean
  className?: string
  /** Narrower panel for form rows. */
  compact?: boolean
}

const FORMATS: ColorFormat[] = ["hex", "hex8", "rgb", "rgba", "hsl", "hsla"]

const EyeDropperCtor =
  typeof window !== "undefined"
    ? (
        window as Window & {
          EyeDropper?: new () => {
            open: () => Promise<{ sRGBHex: string }>
          }
        }
      ).EyeDropper
    : undefined

function useEyeDropperSupported() {
  const [ok, setOk] = React.useState(false)
  React.useEffect(() => {
    setOk(typeof EyeDropperCtor === "function")
  }, [])
  return ok
}

function SaturationArea({
  hsva,
  disabled,
  readOnly,
  onChange,
}: {
  hsva: HsvaColor
  disabled?: boolean
  readOnly?: boolean
  onChange: (next: Partial<HsvaColor>) => void
}) {
  const ref = React.useRef<HTMLDivElement>(null)
  const hueColor = hsvaToHex({ h: hsva.h, s: 100, v: 100, a: 1 })

  const updateFromPointer = React.useCallback(
    (clientX: number, clientY: number) => {
      const el = ref.current
      if (!el || disabled || readOnly) return
      const rect = el.getBoundingClientRect()
      const x = clamp01((clientX - rect.left) / rect.width)
      const y = clamp01((clientY - rect.top) / rect.height)
      onChange({ s: x * 100, v: (1 - y) * 100 })
    },
    [disabled, readOnly, onChange]
  )

  return (
    <div
      ref={ref}
      role="slider"
      tabIndex={disabled || readOnly ? -1 : 0}
      aria-label="Saturation and brightness"
      aria-valuetext={`Saturation ${Math.round(hsva.s)}%, brightness ${Math.round(hsva.v)}%`}
      data-slot="color-picker-saturation"
      className={cn(
        "relative h-40 w-full cursor-crosshair touch-none overflow-hidden rounded-md border border-border/70",
        (disabled || readOnly) && "pointer-events-none cursor-not-allowed opacity-50"
      )}
      style={{
        backgroundImage: `
          linear-gradient(to top, #000, transparent),
          linear-gradient(to right, #fff, transparent),
          linear-gradient(${hueColor}, ${hueColor})
        `,
      }}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId)
        updateFromPointer(e.clientX, e.clientY)
      }}
      onPointerMove={(e) => {
        if (e.buttons !== 1) return
        updateFromPointer(e.clientX, e.clientY)
      }}
      onKeyDown={(e) => {
        if (disabled || readOnly) return
        const step = e.shiftKey ? 5 : 1
        if (e.key === "ArrowRight") {
          e.preventDefault()
          onChange({ s: Math.min(100, hsva.s + step) })
        } else if (e.key === "ArrowLeft") {
          e.preventDefault()
          onChange({ s: Math.max(0, hsva.s - step) })
        } else if (e.key === "ArrowUp") {
          e.preventDefault()
          onChange({ v: Math.min(100, hsva.v + step) })
        } else if (e.key === "ArrowDown") {
          e.preventDefault()
          onChange({ v: Math.max(0, hsva.v - step) })
        }
      }}
    >
      <div
        className="pointer-events-none absolute size-4 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-white shadow-md"
        style={{
          left: `${hsva.s}%`,
          top: `${100 - hsva.v}%`,
          backgroundColor: hsvaToHex(hsva, false),
        }}
      />
    </div>
  )
}

function clamp01(n: number) {
  return Math.min(1, Math.max(0, n))
}

function SwatchButton({
  color,
  selected,
  disabled,
  onSelect,
}: {
  color: string
  selected?: boolean
  disabled?: boolean
  onSelect: () => void
}) {
  return (
    <button
      type="button"
      aria-label={`Select ${color}`}
      aria-pressed={selected}
      disabled={disabled}
      onClick={onSelect}
      className={cn(
        "size-7 cursor-pointer rounded-md border border-border/70 shadow-xs transition-transform hover:scale-105 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100",
        selected && "ring-2 ring-ring ring-offset-2 ring-offset-background"
      )}
      style={{
        backgroundColor: color,
        backgroundImage:
          parseColor(color)?.a !== undefined && (parseColor(color)?.a ?? 1) < 1
            ? "linear-gradient(45deg, #ccc 25%, transparent 25%), linear-gradient(-45deg, #ccc 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #ccc 75%), linear-gradient(-45deg, transparent 75%, #ccc 75%)"
            : undefined,
        backgroundSize: "8px 8px",
        backgroundPosition: "0 0, 0 4px, 4px -4px, -4px 0",
      }}
    />
  )
}

function ColorPicker({
  value: valueProp,
  defaultValue = "#3B82F6",
  onValueChange,
  format: formatProp,
  defaultFormat = "hex",
  onFormatChange,
  swatches = DEFAULT_SWATCHES,
  swatchColumns = 6,
  disabledSwatches = [],
  recentColors: recentProp,
  defaultRecentColors = [],
  onRecentColorsChange,
  showOpacity = false,
  showEyeDropper = false,
  showCopy = true,
  showFormatSelect = true,
  showSwatches = false,
  showRecent = false,
  disabled = false,
  readOnly = false,
  className,
  compact = false,
}: ColorPickerProps) {
  const eyeDropperOk = useEyeDropperSupported()
  const isValueControlled = valueProp !== undefined
  const isFormatControlled = formatProp !== undefined
  const isRecentControlled = recentProp !== undefined

  const [uncontrolledHsva, setUncontrolledHsva] = React.useState(
    () => parseColor(defaultValue) ?? { h: 217, s: 91, v: 96, a: 1 }
  )
  const [uncontrolledFormat, setUncontrolledFormat] =
    React.useState<ColorFormat>(defaultFormat)
  const [uncontrolledRecent, setUncontrolledRecent] =
    React.useState<string[]>(defaultRecentColors)
  const [draft, setDraft] = React.useState("")
  const [copied, setCopied] = React.useState(false)

  const format = isFormatControlled ? formatProp : uncontrolledFormat
  const recent = isRecentControlled ? recentProp : uncontrolledRecent

  const hsva = React.useMemo(() => {
    if (!isValueControlled) return uncontrolledHsva
    return parseColor(valueProp) ?? uncontrolledHsva
  }, [isValueControlled, valueProp, uncontrolledHsva])

  const formatted = formatColor(hsva, format)
  const rgba = hsvaToRgba(hsva)

  React.useEffect(() => {
    setDraft(formatted)
  }, [formatted])

  const commitHsva = React.useCallback(
    (next: HsvaColor, pushRecent = false) => {
      if (disabled || readOnly) return
      if (!isValueControlled) setUncontrolledHsva(next)
      const out = formatColor(next, format)
      onValueChange?.(out, { hsva: next, format })
      if (pushRecent && showRecent) {
        const hex = hsvaToHex(next, next.a < 1)
        const nextRecent = [
          hex,
          ...recent.filter((c) => !colorsEqual(c, hex)),
        ].slice(0, 8)
        if (!isRecentControlled) setUncontrolledRecent(nextRecent)
        onRecentColorsChange?.(nextRecent)
      }
    },
    [
      disabled,
      readOnly,
      isValueControlled,
      format,
      onValueChange,
      showRecent,
      recent,
      isRecentControlled,
      onRecentColorsChange,
    ]
  )

  const patchHsva = React.useCallback(
    (partial: Partial<HsvaColor>) => {
      commitHsva({ ...hsva, ...partial })
    },
    [commitHsva, hsva]
  )

  const setFormat = (next: ColorFormat) => {
    if (!isFormatControlled) setUncontrolledFormat(next)
    onFormatChange?.(next)
    const out = formatColor(hsva, next)
    onValueChange?.(out, { hsva, format: next })
    setDraft(out)
  }

  const commitDraft = () => {
    const parsed = parseColor(draft)
    if (!parsed) {
      setDraft(formatted)
      return
    }
    commitHsva(parsed, true)
  }

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(formatted)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1500)
    } catch {
      // ignore
    }
  }

  const handleEyeDropper = async () => {
    if (!EyeDropperCtor || disabled || readOnly) return
    try {
      const dropper = new EyeDropperCtor()
      const result = await dropper.open()
      const parsed = parseColor(result.sRGBHex)
      if (parsed) commitHsva(parsed, true)
    } catch {
      // user cancelled or unsupported
    }
  }

  const locked = disabled || readOnly

  return (
    <div
      data-slot="color-picker"
      data-compact={compact ? "true" : undefined}
      className={cn(
        "flex w-full flex-col gap-3 rounded-[12px] border border-border/70 bg-card p-3 shadow-soft",
        compact ? "max-w-[220px] p-2.5" : "max-w-[280px]",
        className
      )}
    >
      <SaturationArea
        hsva={hsva}
        disabled={disabled}
        readOnly={readOnly}
        onChange={patchHsva}
      />

      <div className="flex items-center gap-2">
        <div
          className="size-10 shrink-0 overflow-hidden rounded-md border border-border/70"
          style={{
            backgroundImage:
              "linear-gradient(45deg, #c4c4c4 25%, transparent 25%), linear-gradient(-45deg, #c4c4c4 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #c4c4c4 75%), linear-gradient(-45deg, transparent 75%, #c4c4c4 75%)",
            backgroundSize: "8px 8px",
            backgroundPosition: "0 0, 0 4px, 4px -4px, -4px 0",
          }}
        >
          <div
            className="size-full"
            style={{ backgroundColor: `rgba(${rgba.r},${rgba.g},${rgba.b},${rgba.a})` }}
          />
        </div>
        <div className="min-w-0 flex-1 space-y-2">
          <Slider
            min={0}
            max={360}
            step={1}
            value={[hsva.h]}
            disabled={locked}
            onValueChange={([h]) => patchHsva({ h })}
            className="[&_[data-slot=slider-track]]:h-2.5 [&_[data-slot=slider-track]]:bg-[linear-gradient(to_right,#f00,#ff0,#0f0,#0ff,#00f,#f0f,#f00)] [&_[data-slot=slider-range]]:bg-transparent"
            aria-label="Hue"
          />
          {showOpacity ? (
            <div className="space-y-1">
              <Slider
                min={0}
                max={100}
                step={1}
                value={[Math.round(hsva.a * 100)]}
                disabled={locked}
                onValueChange={([pct]) => patchHsva({ a: pct / 100 })}
                className="[&_[data-slot=slider-track]]:h-2.5 [&_[data-slot=slider-track]]:bg-[linear-gradient(45deg,#c4c4c4_25%,transparent_25%),linear-gradient(-45deg,#c4c4c4_25%,transparent_25%),linear-gradient(45deg,transparent_75%,#c4c4c4_75%),linear-gradient(-45deg,transparent_75%,#c4c4c4_75%)] [&_[data-slot=slider-track]]:bg-[length:8px_8px] [&_[data-slot=slider-range]]:bg-transparent"
                aria-label="Opacity"
                style={
                  {
                    // colored overlay via CSS variable on track using box-shadow hack avoided —
                    // show percent below
                  } as React.CSSProperties
                }
              />
              <p className="text-xs text-muted-foreground">
                Opacity {Math.round(hsva.a * 100)}%
              </p>
            </div>
          ) : null}
        </div>
      </div>

      <div className="flex flex-col gap-2">
        {showFormatSelect ? (
          <div className="flex flex-wrap gap-1">
            {FORMATS.map((f) => (
              <Button
                key={f}
                type="button"
                size="xs"
                variant={format === f ? "secondary" : "ghost"}
                disabled={locked}
                className="h-7 cursor-pointer px-2 uppercase"
                onClick={() => setFormat(f)}
              >
                {f}
              </Button>
            ))}
          </div>
        ) : null}

        <InputGroup data-disabled={disabled ? "true" : undefined}>
          <InputGroupInput
            value={draft}
            readOnly={readOnly}
            disabled={disabled}
            spellCheck={false}
            aria-label="Color value"
            onChange={(e) => setDraft(e.target.value)}
            onBlur={commitDraft}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                commitDraft()
              }
            }}
          />
          <InputGroupAddon align="inline-end">
            {showEyeDropper && eyeDropperOk ? (
              <InputGroupButton
                size="icon-xs"
                disabled={locked}
                aria-label="Pick color from screen"
                onClick={() => {
                  void handleEyeDropper()
                }}
              >
                <PipetteIcon className="size-3.5" />
              </InputGroupButton>
            ) : null}
            {showCopy ? (
              <InputGroupButton
                size="icon-xs"
                disabled={disabled}
                aria-label={copied ? "Copied" : "Copy color"}
                onClick={() => {
                  void handleCopy()
                }}
              >
                {copied ? <CheckIcon /> : <CopyIcon />}
              </InputGroupButton>
            ) : null}
          </InputGroupAddon>
        </InputGroup>
      </div>

      {showRecent && recent.length > 0 ? (
        <div className="space-y-1.5">
          <p className="text-xs font-medium text-muted-foreground">Recent</p>
          <div
            className="grid gap-1.5"
            style={{
              gridTemplateColumns: `repeat(${swatchColumns}, minmax(0, 1fr))`,
            }}
          >
            {recent.map((c) => (
              <SwatchButton
                key={c}
                color={c}
                selected={colorsEqual(c, formatted)}
                disabled={locked}
                onSelect={() => {
                  const parsed = parseColor(c)
                  if (parsed) commitHsva(parsed)
                }}
              />
            ))}
          </div>
        </div>
      ) : null}

      {showSwatches ? (
        <div className="space-y-1.5">
          <p className="text-xs font-medium text-muted-foreground">Swatches</p>
          <div
            className="grid gap-1.5"
            style={{
              gridTemplateColumns: `repeat(${swatchColumns}, minmax(0, 1fr))`,
            }}
          >
            {swatches.map((c) => {
              const isDisabled =
                locked ||
                disabledSwatches.some((d) => colorsEqual(d, c))
              return (
                <SwatchButton
                  key={c}
                  color={c}
                  selected={colorsEqual(c, formatted)}
                  disabled={isDisabled}
                  onSelect={() => {
                    const parsed = parseColor(c)
                    if (parsed) commitHsva(parsed, true)
                  }}
                />
              )
            })}
          </div>
        </div>
      ) : null}
    </div>
  )
}

export { ColorPicker }
